"""First individually solved segment of the fixed second import review batch."""
import pathlib,json,hashlib,collections
R=pathlib.Path(__file__).resolve().parents[1]
manifest=json.loads((R/'docs/QUESTION-REVIEW-BATCHES-2026-10-17.json').read_text())
sources=json.loads((R/'docs/QUESTION-REVIEW-BATCH-02-SOURCES-2026-10-17.json').read_text())
originals={q['id']:q for p in (R/'app/imports').glob('*.json') for q in json.loads(p.read_text())['questions']}
rows=[]
def add(n,key,solution,explanation,refs,topic='t-6-1',decision='confirmed',fix=''):
 q=originals[manifest['batches'][1]['questionIds'][n-1]]
 assert decision=='confirmed' or fix
 rows.append(dict(position=n,id=q['id'],batch='import-review-02',reviewedAt='2026-10-17',decision=decision,solvedOption=key,solution=solution,explanation=explanation,requiredCorrectionOrHoldReason=fix,proposedTopicId=topic,scope='PSC common',evidence=[dict(sourceId=r,url=sources[r]['url'],locator='Dated primary announcement; factual paragraph or results table described in explanation') for r in refs.split()],sourceTextSha256=hashlib.sha256((q['prompt']+'\n'+q['answer']).encode()).hexdigest(),releaseStatus='review-recorded',scoredEligible=False))
add(1,'B','John Ternus','Apple’s 20 April 2026 succession announcement specifies Ternus as CEO effective 1 September 2026. The official newsroom also records Cook’s final CEO day on 31 August. The question concerns the transition date, not a timeless incumbent.','turn116search0 turn116search4',topic='t-5-5')
add(2,'C','Bishkek, Kyrgyzstan','The SCO’s 1 September 2026 meeting report identifies Yrys-Ordo Congress Hall in Bishkek and the organisation’s twenty-fifth anniversary. It calls this the twenty-sixth Council of Heads of State meeting; the anniversary and meeting number are different measures.','turn116search1',topic='t-1-9')
add(3,'B','Shravana Purnima','The PMO greeting of 28 August 2026 explicitly associates World Sanskrit Day with Shravana Purnima. This lunar observance does not have one fixed Gregorian calendar date.','turn116search2')
add(4,'C','R. Praggnanandhaa','The organiser names Praggnanandhaa the 2026 overall Grand Chess Tour champion and final winner, defeating Fabiano Caruana. Its release establishes his own first title but does not itself supply a complete historical first-Indian comparison.','turn116search3',decision='correction_required',fix='Ask who won the 2026 overall Grand Chess Tour title; omit first-Indian unless checked against the complete historical champions list.')
add(5,'B','Major Dhyan Chand','The 2026 Sports Ministry event announcement states that 29 August commemorates the birth anniversary of Major Dhyan Chand. The special programme on 27 August does not change the annual observance date.','turn114search7')
add(6,'B','AIS-119 and AIS-153','ICAT’s official 26 August 2026 release names both standards and Synaty Automotive’s fifteen-metre multi-axle sleeper bus compliance certificate. These are the standards in this specific certification announcement, not a statement that other vehicle rules never apply.','turn114search1',topic='t-2-6')
add(7,None,'The proposed Sher name remains unauthenticated from a primary naming announcement','The Defence Ministry establishes the India–Russia joint venture and production at Korwa, but the retrieved official source does not establish the Sher naming claim or a wholly Indian-origin design. Media reports alone were not used to authenticate this key.','turn114search2',topic='t-5-9',decision='held',fix='Retrieve an IRRPL, Kalashnikov or Ministry naming announcement. Distinguish local components/manufacture from the origin of the AK-203 design; do not publish the candidate name as verified.')
add(8,'C','Ten years since the August 2016 app rollout','NPCI’s own product booklet distinguishes the 11 April 2016 pilot launch from bank UPI-app uploads beginning on 25 August 2016. Subtracting 2016 from 2026 gives ten, but the broad completed-years wording obscures the milestone being counted.','turn117search3',topic='t-2-3',decision='correction_required',fix='Ask: On 25 August 2026, how many years had elapsed since banks began uploading UPI-enabled apps to Google Play? Preserve the separate April pilot date.')
add(9,'C','Ajit Doval is the announced Indian representative','China’s Foreign Ministry briefing of 24 August 2026 announces Doval and Wang Yi as co-chairs for the twenty-fifth round in Beijing on 25 August. A prospective briefing authenticates the announced representative but does not independently prove the meeting took place as planned.','turn117search2',topic='t-1-9',decision='correction_required',fix='Attribute the question to the 24 August official briefing and ask who was announced to represent India; alternatively retrieve a post-meeting record before asserting completion.')
add(10,'B','23 August','ISRO’s 24 August 2026 account ties National Space Day to Chandrayaan-3’s soft landing on 23 August 2023 and records the 2026 celebration on that date. The announcement or report date is not the observance date.','turn115search1',topic='t-5-4')
add(11,'C','Kajal Dhochak, with the year and changing weight class specified','United World Wrestling records Kajal’s 2026 U20 title at 76 kg after her 2025 title at 72 kg. The import can misleadingly suggest two consecutive titles in the same weight class.','turn115search3',decision='correction_required',fix='Ask which Indian wrestler won the 2026 U20 women’s 76 kg world title after winning at 72 kg in 2025. Do not imply both titles were at 76 kg.')
add(12,'C','Ten lakh tonnes of raw sugar','The 21 August 2026 Consumer Affairs release permits duty-free import of ten lakh metric tonnes of raw sugar to augment availability. This is the dated decision, not an open-ended entitlement to import any sugar quantity duty-free.','turn115search4',topic='t-2-5')
assert [r['position'] for r in rows]==list(range(1,13))
report=dict(batchId='import-review-02',checkedAt='2026-10-17',positions=[1,12],reviewed=12,counts=dict(collections.Counter(r['decision'] for r in rows)),remainingInBatch=len(manifest['batches'][1]['questionIds'])-12,policy='Source-backed review record. Corrections/holds not approved; release decisions are separate and never inferred from imported keys.',items=rows)
(R/'docs/QUESTION-REVIEW-BATCH-02-PART01-2026-10-17.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
lines=['# Import review batch 2 — first twelve questions','',f"Reviewed:12. Counts:{report['counts']}. Remaining in this batch:{report['remainingInBatch']}.",'','This is the imported-question review batch, separate from the six curriculum chapter batches. Fixed assignments are unchanged. Seven answers are supported, four stems need precise corrections, and one naming claim remains held. Release status is explicit in each record.','']
for r in rows:
 lines += [f"## {r['position']}. {r['id']} — {r['decision']}",'',r['solution'],r['explanation'],r['requiredCorrectionOrHoldReason'],'Topic: '+r['proposedTopicId']]+['- '+e['url'] for e in r['evidence']]+['']
(R/'docs/QUESTION-REVIEW-BATCH-02-PART01-2026-10-17.md').write_text('\n'.join(lines))
print(report['counts'])
